using System.Text.Json;
namespace LeoLauncher;
sealed class ExtensionManager:BarcaWindow
{
    internal static string Describe(ExtensionManifest manifest,ExtensionStore store){var state=ExtensionCompatibility.Read(manifest,store);return manifest.Name+" · "+manifest.Id+"\n"+string.Join("、",manifest.Commands.Select(c=>c.Title))+"\n宿主范围："+(manifest.HostMin??"不限")+" ～ "+(manifest.HostMax??"不限")+" · "+(state.Compatible?"兼容":"不可用："+string.Join("；",state.Reasons))+"\n依赖："+(manifest.Dependencies is{Length:>0}?string.Join("、",manifest.Dependencies):"旧包未声明额外依赖");}
    public ExtensionManager(Preferences prefs,bool preview=false,ExtensionStore? isolatedStore=null)
    {
        Text="Leo · 扩展模块";ClientSize=new(720,570);StartPosition=FormStartPosition.CenterParent;BackColor=BarcaUi.Canvas;ForeColor=BarcaUi.Text;Font=BarcaUi.Font();var header=BarcaUi.Chrome(this,"扩展模块","独立导入、更新和移除；只调用已公开的本地动作。");var store=isolatedStore??new ExtensionStore(Path.Combine(Store.Root,"modules")){Preferences=prefs};var list=new ListBox{Bounds=new(24,111,672,226),BackColor=BarcaUi.Surface,ForeColor=BarcaUi.Text,BorderStyle=BorderStyle.None,ItemHeight=28};var info=new TextBox{Bounds=new(24,345,672,95),Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BorderStyle=BorderStyle.None,BackColor=BarcaUi.Canvas,ForeColor=BarcaUi.Muted};var status=new Label{Bounds=new(24,491,672,58),ForeColor=BarcaUi.Muted,Font=BarcaUi.Font(8.5f)};ExtensionManifest[] loaded=[];
        void Reload(){loaded=preview&&isolatedStore==null?[]:store.Load();list.Items.Clear();foreach(var m in loaded)list.Items.Add((!ExtensionCompatibility.Read(m,store).Compatible?"不可用 · ":prefs.DisabledExtensions.Contains(m.Id)?"已停用 · ":"已启用 · ")+m.Name+"  v"+m.Version);if(list.Items.Count>0)list.SelectedIndex=0;else info.Text="还没有安装扩展。可导出示例，修改后再导入。";if(store.Errors.Count>0)status.Text=string.Join("\n",store.Errors.Take(2));}
