        var import=new BarcaButton{Text="导入 / 更新…",Bounds=new(24,451,150,32)};import.Click+=(_,_)=>{if(preview)return;using var picker=new OpenFileDialog{Filter="Leo扩展模块|*.json;*.zip",Title="导入LeoModule/1模块"};if(picker.ShowDialog(this)!=DialogResult.OK)return;try{bool package=Path.GetExtension(picker.FileName).Equals(".zip",StringComparison.OrdinalIgnoreCase);var manifest=package?store.InspectPackage(picker.FileName):store.Inspect(picker.FileName);string actions=string.Join("\n",manifest.Commands.Select(c=>c.Title+" → "+c.Action+(manifest.Runtime=="actions"&&c.Value.Length>0?" · "+(c.Value.Length>100?c.Value[..100]+"…":c.Value):"")));if(UiDialogs.Show(this,manifest.Name+" v"+manifest.Version+(manifest.Runtime=="stdio"?"\n独立进程模块：执行时运行包内程序，权限与当前用户相同。":"\n声明式模块：调用已有本地动作。")+"\n\n"+actions,"确认安装这些动作",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;if(package)store.InstallPackage(picker.FileName);else store.Install(manifest);EntryContributions.RefreshExtensions(prefs);status.Text=store.LastWarning??"已安装，指令入口立即可用。";Reload();}catch(Exception e){status.Text=e.Message;}};
        var enable=new BarcaButton{Text="启用 / 停用",Bounds=new(184,451,145,32)};enable.Click+=(_,_)=>{if(preview||list.SelectedIndex<0)return;string id=loaded[list.SelectedIndex].Id;if(!prefs.DisabledExtensions.Remove(id))prefs.DisabledExtensions.Add(id);Store.Save(prefs);EntryContributions.RefreshExtensions(prefs);Reload();};
        var remove=new BarcaButton{Text="移除",Bounds=new(339,451,105,32)};remove.Click+=(_,_)=>{if(preview||list.SelectedIndex<0)return;var m=loaded[list.SelectedIndex];if(UiDialogs.Show(this,"移除扩展“"+m.Name+"”？","移除扩展",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;try{store.Remove(m.Id);prefs.DisabledExtensions.Remove(m.Id);Store.Save(prefs);EntryContributions.RefreshExtensions(prefs);Reload();}catch(Exception e){status.Text=e.Message;}};
